import{_ as n,a0 as i,w as d,s as l,I as o,x as e,a1 as s,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"隐藏功能！在 DuckDuckGo 搜索引擎中，你可以做这 25 件有趣的事情 | LCTT x X-CMD","titleTemplate":false,"description":"隐藏功能！在 DuckDuckGo 搜索引擎中，你可以做这 25 件有趣的事情 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"隐藏功能！在 DuckDuckGo 搜索引擎中，你可以做这 25 件有趣的事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"隐藏功能！在 DuckDuckGo 搜索引擎中，你可以做这 25 件有趣的事情 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220514 Hidden Features! 25 Fun Things You Can Do With DuckDuckGo Search Engine","title":"隐藏功能！在 DuckDuckGo 搜索引擎中，你可以做这 25 件有趣的事情","tag":"202206","desc":""},"relativePath":"202206/20220514 Hidden Features! 25 Fun Things You Can Do With DuckDuckGo Search Engine.md","filePath":"[post].md"}'),c={name:"202206/20220514 Hidden Features! 25 Fun Things You Can Do With DuckDuckGo Search Engine.md"};function h(m,a,u,g,f,k){const t=i("Link");return d(),l("div",null,[a[21]||(a[21]=o("h1",{id:"隐藏功能-在-duckduckgo-搜索引擎中-你可以做这-25-件有趣的事情",tabindex:"-1"},[e("隐藏功能！在 DuckDuckGo 搜索引擎中，你可以做这 25 件有趣的事情 "),o("a",{class:"header-anchor",href:"#隐藏功能-在-duckduckgo-搜索引擎中-你可以做这-25-件有趣的事情","aria-label":"Permalink to “隐藏功能！在 DuckDuckGo 搜索引擎中，你可以做这 25 件有趣的事情”"},"​")],-1)),a[22]||(a[22]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202206/11/142806ebr5xtzgcwcr5955.jpg",alt:""})],-1)),o("p",null,[a[1]||(a[1]=e("比起无处不在的 Google，",-1)),s(t,{href:"https://itsfoss.com/privacy-search-engines/"},{default:p(()=>[...a[0]||(a[0]=[e("有些搜索引擎替代品更加尊重隐私",-1)])]),_:1}),a[2]||(a[2]=e("，而 DuckDuckGo 就是其中之一。",-1))]),a[23]||(a[23]=r('<p>最近，这个搜索引擎有了很大的改进，搜索一般网页十分顺畅。在搜索本地地点方面，则还远不及 Google。</p><p>不过，DuckDuckGo（简称为 DDG）有一些很酷的功能，大部分用户还没注意到。如果你是一位 DDG 狂热粉，你可能会喜欢用这些小技巧来提升你的搜索体验。</p><h3 id="_1、跳转到特定网页" tabindex="-1">1、跳转到特定网页 <a class="header-anchor" href="#_1、跳转到特定网页" aria-label="Permalink to “1、跳转到特定网页”">​</a></h3><p>在你最喜欢的网站名称前输入 <code>!</code> 即可直接进入这个网站。则类似于 Google 的 “运气不错” 功能，但用 DDG 的话来说，这就叫 “叹号搜索”。</p><p>有一些网站有缩写形式，开始输入时便会提示。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/duckduckgo-bang-feature-800x449.png" alt="duckduckgo bang feature"></p><p>在网站名后面输入搜索词，就可以直接抵达那个网站的搜索结果处。</p><h3 id="_2、文本转-ascii" tabindex="-1">2、文本转 ASCII <a class="header-anchor" href="#_2、文本转-ascii" aria-label="Permalink to “2、文本转 ASCII”">​</a></h3>',8)),o("p",null,[a[4]||(a[4]=e("Figlet 是一个 ",-1)),s(t,{href:"https://itsfoss.com/funny-linux-commands/"},{default:p(()=>[...a[3]||(a[3]=[e("有趣的 Linux 命令",-1)])]),_:1}),a[5]||(a[5]=e("，可以将任意文本转换为漂亮的 ASCII 画格式。",-1))]),a[24]||(a[24]=r('<p>在任意搜索词前输入 <code>figlet</code>，就会显示 ASCII 输出。无需打开终端。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/figlet-800x272.png" alt="Figlet in DDG"></p><h3 id="_3、检查社交媒体的状态" tabindex="-1">3、检查社交媒体的状态 <a class="header-anchor" href="#_3、检查社交媒体的状态" aria-label="Permalink to “3、检查社交媒体的状态”">​</a></h3><p>在某个人的 Twitter 名前加上 <code>@</code>，就会显示 TA 的状态（关注者等）。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/itsfoss-twitter-800x278.jpg" alt="Itsfoss Twitter"></p><h3 id="_4、生成强密码" tabindex="-1">4、生成强密码 <a class="header-anchor" href="#_4、生成强密码" aria-label="Permalink to “4、生成强密码”">​</a></h3><p>输入 <code>password</code> 并加上需要的字符数，就可以生成一个独特的强密码。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/password-30-800x185.jpg" alt="Generating password in DuckDuckGo"></p><h3 id="_5、生成随机密码短语" tabindex="-1">5、生成随机密码短语 <a class="header-anchor" href="#_5、生成随机密码短语" aria-label="Permalink to “5、生成随机密码短语”">​</a></h3><p>输入 <code>random passphrase</code> 可生成一段密码短语，通常长度为 4 个词。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/random-pqssphrase-800x179.png" alt="Random Passphrase"></p><h3 id="_6、获取一份速查表" tabindex="-1">6、获取一份速查表 <a class="header-anchor" href="#_6、获取一份速查表" aria-label="Permalink to “6、获取一份速查表”">​</a></h3><p>在需要看速查表的搜索词后面，可输入 <code>cheatsheet</code>。如果要搜索的东西有速查表，就会立即显示在搜索页面。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/vim-cheatsheet-800x367.png" alt="Vim Cheatsheet"></p><h3 id="_7、通过色码获取颜色" tabindex="-1">7、通过色码获取颜色 <a class="header-anchor" href="#_7、通过色码获取颜色" aria-label="Permalink to “7、通过色码获取颜色”">​</a></h3><p>输入 <code>color</code> 并加上你想查的颜色的十六进制码，便可显示这个颜色。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/color-800x289.jpg" alt="Color"></p><h3 id="_8、生成随机数" tabindex="-1">8、生成随机数 <a class="header-anchor" href="#_8、生成随机数" aria-label="Permalink to “8、生成随机数”">​</a></h3><p>搜索 <code>random number</code> 会输出一个 0 到 1 之间的随机数。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/random-number-800x235.png" alt="Random Number"></p><p>你也可以指定需要的范围。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/random-number-between-1-and-1000-800x244.png" alt="Random Number between 1 and 1000"></p><h3 id="_9、转换为二进制等形式" tabindex="-1">9、转换为二进制等形式 <a class="header-anchor" href="#_9、转换为二进制等形式" aria-label="Permalink to “9、转换为二进制等形式”">​</a></h3><p>输入一个二进制数并加上 <code>binary</code>，可将其从二进制转换为十进制。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/binary-800x184.png" alt="Binary to Decimal"></p><p>类似地，它也能用于十六进制和八进制，但我不清楚它们的处理逻辑。</p><h3 id="_10、寻找韵词" tabindex="-1">10、寻找韵词 <a class="header-anchor" href="#_10、寻找韵词" aria-label="Permalink to “10、寻找韵词”">​</a></h3><p>输入 <code>what rhymes with</code> 并带上要找同韵词的词语。作诗能力变强了，对吧？</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/What-rhymes-with-rain-800x257.png" alt="What rhymes with rain"></p><h3 id="_11、获取拉马努金数、圆周率等常数" tabindex="-1">11、获取拉马努金数、圆周率等常数 <a class="header-anchor" href="#_11、获取拉马努金数、圆周率等常数" aria-label="Permalink to “11、获取拉马努金数、圆周率等常数”">​</a></h3><p>输入想获取数值的常数名，便可在搜索结果中看到它。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/ramanujan-number-800x238.png" alt="Ramanujan Number"></p><h3 id="_12、查询现在谁在太空中" tabindex="-1">12、查询现在谁在太空中 <a class="header-anchor" href="#_12、查询现在谁在太空中" aria-label="Permalink to “12、查询现在谁在太空中”">​</a></h3><p>输入 <code>people in space</code> 获取当前在太空中的人员名单。同时还会显示他们在太空中居住的时间。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/people-in-space-800x313.jpg" alt="People in Space"></p><h3 id="_13、查询网页是否无法访问" tabindex="-1">13、查询网页是否无法访问 <a class="header-anchor" href="#_13、查询网页是否无法访问" aria-label="Permalink to “13、查询网页是否无法访问”">​</a></h3><p>如果你想知道某个网站是你无法访问了，还是大家都无法访问了，只需在搜索词中输入 <code>is xyz.com down</code>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/is-down-800x204.png" alt="Is down?"></p><h3 id="_14、获取特定话题的名言" tabindex="-1">14、获取特定话题的名言 <a class="header-anchor" href="#_14、获取特定话题的名言" aria-label="Permalink to “14、获取特定话题的名言”">​</a></h3><p>输入一个词并带上 <code>quotes</code>，就会显示与这个词相关的名言。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/life-quotes-800x303.png" alt="Get quotes in DDG"></p><h3 id="_15、获取占位文本" tabindex="-1">15、获取占位文本 <a class="header-anchor" href="#_15、获取占位文本" aria-label="Permalink to “15、获取占位文本”">​</a></h3><p>搜索 <code>lorem ipsum</code> 就可以获取 5 段占位文本。对 Web 开发者应该会有用。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/lorem-ipsum-800x227.png" alt="Lorem ipsum"></p><h3 id="_16、获取任意月份的日历" tabindex="-1">16、获取任意月份的日历 <a class="header-anchor" href="#_16、获取任意月份的日历" aria-label="Permalink to “16、获取任意月份的日历”">​</a></h3><p>在年、月、日后面输入 <code>calendar</code>，就会为你显示该月份的交互式日历。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/calendar-800x331.png" alt="Calendar"></p><h3 id="_17、生成二维码" tabindex="-1">17、生成二维码 <a class="header-anchor" href="#_17、生成二维码" aria-label="Permalink to “17、生成二维码”">​</a></h3><p>在文字、链接等后面输入 <code>qr</code>，就会生成对应的二维码。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/qrcode-800x255.png" alt="QRCode"></p><h3 id="_18、获取一些-css-动画" tabindex="-1">18、获取一些 CSS 动画 <a class="header-anchor" href="#_18、获取一些-css-动画" aria-label="Permalink to “18、获取一些 CSS 动画”">​</a></h3><p>搜索 <code>css animations</code> 以获取一些 CSS 动画例子。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/css-animations-800x385.jpg" alt="CSS Animations"></p><h3 id="_19、展开短链接" tabindex="-1">19、展开短链接 <a class="header-anchor" href="#_19、展开短链接" aria-label="Permalink to “19、展开短链接”">​</a></h3><p>如果有一个 Bitly 链接或其他短链接，但不确定它指向哪里，不必再跳转到充满垃圾信息的网页了，只需展开短链接，看看真正的网址。</p><p>在短链接后面输入关键词 <code>expand</code>，就会显示真正的目标 URL。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/expand-shortened-link-ddg-800x209.png" alt="Expand Link"></p><h3 id="_20、获取特殊字符的-html-代码" tabindex="-1">20、获取特殊字符的 HTML 代码 <a class="header-anchor" href="#_20、获取特殊字符的-html-代码" aria-label="Permalink to “20、获取特殊字符的 HTML 代码”">​</a></h3><p>搜索 <code>html chars</code>，可以获取一份很长的列表，上面有 HTML 实体及其描述，按下后会在结果中显示更多信息。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/html-chars-800x174.png" alt="HTML Chars"></p><h3 id="_21、我用这东西干啥" tabindex="-1">21、我用这东西干啥？ <a class="header-anchor" href="#_21、我用这东西干啥" aria-label="Permalink to “21、我用这东西干啥？”">​</a></h3><p>这功能没什么用。如果你输入 <code>why should I use this?</code> ，它就会在搜索结果顶部显示 <code>cause it&#39;s awesome</code>。显然，DuckDuckGo 在说他自己。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/why-should-i-use-this-800x160.png" alt="Why should I use this?"></p><h3 id="_22、转换大小写" tabindex="-1">22、转换大小写 <a class="header-anchor" href="#_22、转换大小写" aria-label="Permalink to “22、转换大小写”">​</a></h3><p>大小写都可转换。<code>lowercase &lt;大写搜索词&gt;</code> 就会显示小写的结果</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/lowercase-800x179.png" alt="Lowercase"></p><p><code>uppercase &lt;小写搜索词&gt;</code> 就会显示大写的结果。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/uppercase-800x185.png" alt="Uppercase"></p><h3 id="_23、编码-url" tabindex="-1">23、编码 URL <a class="header-anchor" href="#_23、编码-url" aria-label="Permalink to “23、编码 URL”">​</a></h3><p>搜索 <code>encode</code> 并加上 URL，就会给出编码后的结果</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/url-encode-800x177.png" alt="URL Encode"></p><h3 id="_24、motherboard" tabindex="-1">24、Motherboard <a class="header-anchor" href="#_24、motherboard" aria-label="Permalink to “24、Motherboard”">​</a></h3><p>搜索 <code>Motherboard</code> 就会看见左侧的 DuckDuckGo 的 logo 变了。它会显示选好的几个随机 logo。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/motherboard.png" alt="Motherboard"></p><h3 id="_25、获取-html-色码" tabindex="-1">25、获取 HTML 色码 <a class="header-anchor" href="#_25、获取-html-色码" aria-label="Permalink to “25、获取 HTML 色码”">​</a></h3><p>搜索 <code>color codes</code> 便可获得一份颜色表。一样，这个功能多为 Web 开发者和设计师所用。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/color-codes-800x554.png" alt="Color Codes"></p><h3 id="还有很多别的···" tabindex="-1">还有很多别的··· <a class="header-anchor" href="#还有很多别的···" aria-label="Permalink to “还有很多别的···”">​</a></h3><p>我的伙伴 Sreenath 想到本贴的主意。他说 DuckDuckGo 中还有许多 “彩蛋”，我觉得没错。但全部列出来有诸多不便。</p><p>如果你知道更多这样有趣的 DDG 搜索功能，请在评论中分享。如果你又发现了你喜欢的搜索功能，也提出来吧。</p><hr>',81)),o("p",null,[a[7]||(a[7]=e("via: ",-1)),s(t,{href:"https://itsfoss.com/duckduckgo-easter-eggs/"},{default:p(()=>[...a[6]||(a[6]=[e("https://itsfoss.com/duckduckgo-easter-eggs/",-1)])]),_:1})]),o("p",null,[a[12]||(a[12]=e("作者：",-1)),s(t,{href:"https://itsfoss.com/author/sreenath/"},{default:p(()=>[...a[8]||(a[8]=[e("sreenath",-1)])]),_:1}),a[13]||(a[13]=e(" 选题：",-1)),s(t,{href:"https://github.com/lkxed"},{default:p(()=>[...a[9]||(a[9]=[e("lkxed",-1)])]),_:1}),a[14]||(a[14]=e(" 译者：",-1)),s(t,{href:"https://github.com/TravinDreek"},{default:p(()=>[...a[10]||(a[10]=[e("Peaksol",-1)])]),_:1}),a[15]||(a[15]=e(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:p(()=>[...a[11]||(a[11]=[e("wxy",-1)])]),_:1})]),o("p",null,[a[18]||(a[18]=e("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...a[16]||(a[16]=[e("LCTT",-1)])]),_:1}),a[19]||(a[19]=e(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:p(()=>[...a[17]||(a[17]=[e("Linux中国",-1)])]),_:1}),a[20]||(a[20]=e(" 荣誉推出",-1))])])}const D=n(c,[["render",h]]);export{_ as __pageData,D as default};
